<template>
  <div class="home-view bg-light min-vh-100">
    <NavBarVue />

    <b-container fluid class="py-4">
      <b-row class="mb-4 align-items-center">
        <b-col md="6">
          <h4 class="text-dark font-weight-bold mb-1">Painel de Controlo</h4>
          <p class="text-muted small mb-0">
            <b-icon icon="calendar3" class="mr-1"></b-icon>
            <span v-date-format="today"></span> | Bem-vindo ao sistema MBR
          </p>
        </b-col>
        <b-col md="6" class="text-md-right mt-3 mt-md-0">
          <b-button
            variant="mbr-green"
            size="sm"
            @click="syncLoans"
            class="shadow-sm"
          >
            <b-icon icon="arrow-repeat" class="mr-1"></b-icon> Sincronizar Dados
          </b-button>
        </b-col>
      </b-row>

      <b-overlay :show="isLoading" rounded="lg" opacity="0.6">
        <b-row class="mb-4">
          <b-col lg="3" md="6" class="mb-3">
            <b-card
              no-body
              class="stat-card border-0 shadow-sm"
              @click="goToCustomers()"
            >
              <div class="d-flex align-items-center p-3">
                <div class="icon-shape bg-soft-info mr-3">
                  <b-icon icon="people-fill" class="text-info"></b-icon>
                </div>
                <div>
                  <div class="text-muted small font-weight-bold uppercase">
                    Mutuários
                  </div>
                  <h3 class="font-weight-bold mb-0 text-dark">
                    {{ customers.length }}
                  </h3>
                </div>
              </div>
            </b-card>
          </b-col>

          <b-col lg="3" md="6" class="mb-3">
            <b-card no-body class="stat-card border-0 shadow-sm accent-green">
              <div class="d-flex align-items-center p-3">
                <div class="icon-shape bg-mbr-green mr-3 text-white">
                  <b-icon icon="cash-stack"></b-icon>
                </div>
                <div>
                  <div class="text-muted small font-weight-bold uppercase">
                    Total Desembolsado
                  </div>
                  <h3
                    class="font-weight-bold mb-0 text-mbr-green"
                    v-money-format="activeLoans"
                  ></h3>
                </div>
              </div>
            </b-card>
          </b-col>

          <b-col lg="3" md="6" class="mb-3">
            <b-card
              no-body
              class="stat-card border-0 shadow-sm"
              @click="selectLoanList(1)"
            >
              <div class="d-flex align-items-center p-3">
                <div class="icon-shape bg-soft-warning mr-3">
                  <b-icon icon="clock-history" class="text-warning"></b-icon>
                </div>
                <div>
                  <div class="text-muted small font-weight-bold uppercase">
                    Pendente
                  </div>
                  <h3
                    class="font-weight-bold mb-0 text-dark"
                    v-money-format="pendingLoans"
                  ></h3>
                </div>
              </div>
            </b-card>
          </b-col>

          <b-col lg="3" md="6" class="mb-3">
            <b-card
              no-body
              class="stat-card border-0 shadow-sm"
              @click="selectLoanList(2)"
            >
              <div class="d-flex align-items-center p-3">
                <div class="icon-shape bg-soft-danger mr-3">
                  <b-icon icon="x-circle-fill" class="text-danger"></b-icon>
                </div>
                <div>
                  <div class="text-muted small font-weight-bold uppercase">
                    Rejeitado
                  </div>
                  <h3
                    class="font-weight-bold mb-0 text-dark"
                    v-money-format="rejectedLoans"
                  ></h3>
                </div>
              </div>
            </b-card>
          </b-col>
        </b-row>

        <b-row>
          <b-col lg="12">
            <b-card no-body class="border-0 shadow-sm overflow-hidden">
              <b-card-header class="bg-white border-0 py-3">
                <b-row align-v="center">
                  <b-col>
                    <h6 class="font-weight-bold text-dark mb-0">
                      <b-icon
                        icon="calendar-check"
                        class="text-mbr-green mr-2"
                      ></b-icon>
                      Prestações Próximas
                    </h6>
                  </b-col>
                  <b-col class="text-right">
                    <b-form-radio-group
                      v-model="rangeFilter"
                      buttons
                      button-variant="outline-mbr"
                      size="sm"
                      class="mbr-radio-group"
                    >
                      <b-form-radio value="today">Hoje</b-form-radio>
                      <b-form-radio value="7">7 Dias</b-form-radio>
                      <b-form-radio value="30">30 Dias</b-form-radio>
                    </b-form-radio-group>
                  </b-col>
                </b-row>
              </b-card-header>

              <b-table
                responsive
                hover
                :items="filteredUpcoming"
                :fields="weekFields"
                class="mb-0 text-center"
                thead-class="bg-light text-uppercase small text-muted font-weight-bold"
              >
                <template #cell(customer)="data">
                  <div
                    class="d-flex align-items-center justify-content-center text-left"
                  >
                    <div class="avatar-circle mr-2">
                      {{ getCustomerName(data.item.accountNumber).charAt(0) }}
                    </div>
                    <span class="font-weight-bold text-dark">
                      {{ getCustomerName(data.item.accountNumber) }}
                    </span>
                  </div>
                </template>

                <template #cell(amount)="data">
                  <span
                    class="font-weight-bold text-mbr-green"
                    v-money-format="data.item.installment"
                  ></span>
                </template>

                <template #cell(dueDate)="data">
                  <span
                    class="text-dark"
                    v-date-format="data.item.dueDate"
                  ></span>
                </template>

                <template #cell(status)="data">
                  <b-badge
                    :variant="
                      data.item.status === 0 ? 'soft-warning' : 'soft-success'
                    "
                    pill
                    class="px-3 py-1"
                  >
                    {{ data.item.status === 0 ? "Em dívida" : "Pago" }}
                  </b-badge>
                </template>

                <template #cell(actions)="data">
                  <b-button
                    variant="mbr-green-light"
                    size="sm"
                    pill
                    @click="remindCustomer(data.item)"
                  >
                    <b-icon icon="chat-left-dots-fill" class="mr-1"></b-icon>
                    Notificar
                  </b-button>
                </template>
              </b-table>

              <div
                v-if="filteredUpcoming.length === 0"
                class="text-center py-5"
              >
                <b-icon icon="inbox" font-scale="3" variant="light"></b-icon>
                <p class="text-muted mt-2">
                  Nenhuma prestação encontrada para este período.
                </p>
              </div>
            </b-card>
          </b-col>
        </b-row>
      </b-overlay>
    </b-container>

    <b-modal
      hide-footer
      centered
      ref="show-pending-loans"
      :title="selectedLoanDescription"
      header-class="border-0"
      body-class="pt-0"
    >
      <LoansList :selectLoanList="selectedLoanList" />
    </b-modal>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import NavBarVue from "@/components/NavBar";
import moment from "moment";
import LoansList from "@/components/loans/LoansList.vue";

export default {
  data: () => ({
    today: moment(),
    activeLoans: 0,
    pendingLoans: 0,
    rejectedLoans: 0,
    companyLoanList: [],
    selectedLoanDescription: "",
    selectedLoanList: [],
    rangeFilter: "7",
    weekFields: [
      { key: "customer", label: "Mutuário" },
      { key: "amount", label: "Prestação", class: "text-right" },
      { key: "installmentOrder", label: "Ordem" },
      { key: "dueDate", label: "Vencimento", class: "text-right" },
      { key: "status", label: "Status", class: "text-center" },
      { key: "actions", label: "Acções", class: "text-center" },
    ],
  }),

  components: {
    NavBarVue,
    LoansList,
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "users",
      "token",
      "company",
      "companyLoans",
      "accounts",
      "customers",
      "dueInstallments",
      "upcomingInstallments",
      "updatedPassword",
    ]),
    // Prestações que vencem hoje
    dueToday() {
      const start = moment().startOf("day");
      const end = moment().endOf("day");
      return this.upcomingInstallments.filter((item) => {
        const due = moment(item.dueDate);
        return due.isBetween(start, end, undefined, "[]");
      });
    },
    // Próximos 7 dias
    upcoming7() {
      const start = moment().startOf("day");
      const end = moment().add(7, "days").endOf("day");
      return this.upcomingInstallments.filter((item) => {
        const due = moment(item.dueDate);
        return due.isBetween(start, end, undefined, "[]");
      });
    },
    // Próximos 30 dias
    upcoming30() {
      const start = moment().startOf("day");
      const end = moment().add(30, "days").endOf("day");
      return this.upcomingInstallments.filter((item) => {
        const due = moment(item.dueDate);
        return due.isBetween(start, end, undefined, "[]");
      });
    },
    // Lista filtrada pelo período selecionado
    filteredUpcoming() {
      if (this.rangeFilter === "today") return this.dueToday;
      if (this.rangeFilter === "30") return this.upcoming30;
      return this.upcoming7;
    },
  },

  watch: {
    companyLoans: function () {
      this.populateCompanyLoans();
    },
  },

  created() {
    this.checkPasswordStatus();
  },

  methods: {
    selectLoanList(list) {
      if (list == 1) {
        this.selectedLoanDescription = "Financiamentos pendentes.";
        this.selectedLoanList = this.companyLoanList.filter((credit) => {
          return credit.status == 0;
        });
      } else if (list == 2) {
        this.selectedLoanDescription = "Financiamentos rejeitados.";
        this.selectedLoanList = this.companyLoanList.filter((credit) => {
          return credit.status == -1;
        });
      }
      this.$refs["show-pending-loans"].show();
    },

    checkPasswordStatus() {
      this.user.updatedPassword == 1 ? "" : this.$router.replace("/profile");
    },

    goToCustomers() {
      this.$router.replace("/customers");
    },

    openCustomerPanel(accountNumber) {
      const filteredCustomer = this.customers.filter((a) => {
        return a.accountNumber == accountNumber;
      });
      this.$store.commit("SET_CURRENT_CUSTOMER", filteredCustomer[0]);
      this.$router.replace("/customer");
    },

    syncLoans() {
      if (this.user.userRole === 1) {
        this.companyLoanList = this.companyLoans;
      } else {
        const list = this.companyLoans.filter((a) => {
          return a.creditManager == this.user.id;
        });
        this.companyLoanList = list;
      }
    },

    populateCompanyLoans() {
      this.syncLoans();
      // Disbursed Loans
      const disbursedLoan = this.companyLoanList.filter((credit) => {
        return credit.status == 1;
      });
      this.activeLoans = disbursedLoan.reduce((sum, p) => sum + p.amount, 0);

      // Pending Loans
      const pendingLoan = this.companyLoanList.filter((credit) => {
        return credit.status == 0;
      });
      this.pendingLoans = pendingLoan.reduce((sum, p) => sum + p.amount, 0);

      // Disbursed Loans
      const rejectedLoan = this.companyLoanList.filter((credit) => {
        return credit.status == -1;
      });

      this.rejectedLoans = rejectedLoan.reduce((sum, p) => sum + p.amount, 0);
    },

    getCustomerName(accountNumber) {
      const found = this.customers.find(
        (c) => c.accountNumber === accountNumber
      );
      return found ? found.customerName : accountNumber;
    },

    remindCustomer(installment) {
      const customer = this.customers.find(
        (c) => c.accountNumber === installment.accountNumber
      );
      if (!customer || !customer.customerPhone) {
        this.$bvToast.toast(
          "Não foi possível encontrar o contacto do cliente.",
          {
            title: "Aviso!",
            variant: "warning",
            solid: true,
            toaster: "b-toaster-top-center",
            autoHideDelay: 5000,
          }
        );
        return;
      }

      const smsBody = `Prezado(a) ${
        customer.customerName
      },\n\nLembramos que a ${
        installment.installmentOrder
      } no valor de ${installment.installment.toFixed(
        2
      )} MZN vence em breve. Caso já tenha efectuado o pagamento, por favor desconsidere esta mensagem.\n\n${
        this.company.companyName
      }`;

      const payload = {
        receipient: customer.customerPhone,
        accountNumber: customer.accountNumber,
        sender: this.company.smsSender,
        companyId: this.company.id,
        smsBody,
      };

      this.$store.dispatch("sendSMSMessage", payload);
    },
  },
};
</script>
<style scoped>
/* CORES DA MARCA MBR */
.text-mbr-green {
  color: #009640 !important;
}
.bg-mbr-green {
  background-color: #009640 !important;
}

/* ESTILO DOS CARDS DE ESTATÍSTICA */
.stat-card {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  cursor: pointer;
  border-radius: 12px;
}
.stat-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.08) !important;
}
.accent-green {
  border-left: 5px solid #009640 !important;
}

.icon-shape {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  font-size: 1.25rem;
}

/* VARIAÇÕES SOFT (FUNDO CLARO) */
.bg-soft-info {
  background-color: rgba(23, 162, 184, 0.1);
}
.bg-soft-warning {
  background-color: rgba(255, 193, 7, 0.1);
}
.bg-soft-danger {
  background-color: rgba(220, 53, 69, 0.1);
}

/* BOTÕES E RADIOS MBR */
.btn-mbr-green {
  background-color: #009640;
  color: white;
  border-radius: 8px;
}
.btn-mbr-green:hover {
  background-color: #007a33;
  color: white;
}

.btn-mbr-green-light {
  background-color: rgba(0, 150, 64, 0.1);
  color: #009640;
  border: none;
  font-weight: 600;
}
.btn-mbr-green-light:hover {
  background-color: #009640;
  color: white;
}

/* ESTILO DO FILTRO DE RÁDIO */
.mbr-radio-group .btn-outline-mbr {
  border-color: #dee2e6;
  color: #6c757d;
  background-color: white;
}
.mbr-radio-group .btn-outline-mbr:not(:disabled):not(.disabled).active {
  background-color: #009640;
  border-color: #009640;
  color: white;
}

/* AVATAR SIMPLES */
.avatar-circle {
  width: 35px;
  height: 35px;
  background-color: #e9ecef;
  color: #495057;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
  font-size: 0.8rem;
}

/* BADGES PERSONALIZADAS */
.badge-soft-warning {
  background-color: #fff3cd;
  color: #856404;
}
.badge-soft-success {
  background-color: #d4edda;
  color: #155724;
}

.uppercase {
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-size: 0.7rem;
}
</style>
